{
  "permissions": {
    "allow": [
      "Bash(git push origin main)",
      "Bash(git push origin main:claude/worker-brief-fable-vnnuv8)",
      "Bash(git push origin main:blinded-fable)",
      "Bash(git push -q origin main)",
      "Bash(git push -q origin main:claude/worker-brief-fable-vnnuv8)",
      "Bash(git push -q origin main:blinded-fable)"
    ]
  },
  "hooks": {
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "/home/user/fortress-transcripts-blinded/scripts/backup.sh"
          },
          {
            "type": "command",
            "command": "/home/user/fortress/.claude/hooks/model-check.sh"
          },
          {
            "type": "command",
            "command": "/home/user/fortress/.claude/hooks/git-check-off.sh"
          },
          {
            "type": "command",
            "command": "rm -f ~/.claude/curator-words-reminder.fired"
          }
        ]
      }
    ],
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "/home/user/fortress/.claude/hooks/git-check-off.sh"
          }
        ]
      },
      {
        "matcher": "compact",
        "hooks": [
          {
            "type": "command",
            "command": "printf \"%s\\n\" \"{\\\"hookSpecificOutput\\\":{\\\"hookEventName\\\":\\\"SessionStart\\\",\\\"additionalContext\\\":\\\"This session was just compacted. Before anything else, check the serving model by running explorations/coordinator/tools/model-now.sh, and with the get_session tool and no session_id only if it prints nothing; if it is neither Opus nor Fable, tell the curator first. Then boot: load the fortress-repo skill, then the coordinator skill, with the Skill tool, so that each is its current version and the worker skill's core comes first, and follow the coordinator skill's section The boot, step by step, as the section gives them now, or in the form that the curator names if he names one. Do not boot from a copy of a skill or of a part shown from before the compaction: it can be cut or an older version, so load each skill with the Skill tool and read each part from disk before its work. Only then continue what the summary describes, and say that the boot was done.\\\"}}\""
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Bash|Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "/home/user/fortress/.claude/hooks/curator-words-reminder.sh",
            "timeout": 10
          }
        ]
      }
    ]
  }
}
